steps.script:
for i in range(20):
	if TutorialManager.current_step_id() == "deploy_grots":
		break
	TutorialManager.skip_step()
return TutorialManager.current_step_id()

var rd = tree.root.get_node_or_null("Main/RollOffDialog")
if not rd.has_meta("tutorial_exit_button"):
	return "missing"
var b = rd.get_meta("tutorial_exit_button")
return "%s|%s" % [str(b.text), str(b.is_visible_in_tree())]

var stray = []
for c in tree.root.get_children():
	if c is Window and c != tree.root and c.visible:
		stray.append(str(c.name))
return stray.size()
